// Package dojo holds helpers shared by every dojo's tests: a trace recorder
// whose events the web UI draws as a timeline.
//
// 这个包由运行器自动生成，每次运行测试都会覆盖，不要修改。
// Generated by the runner and overwritten on every test run; do not edit.
package dojo

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"
)

// Event is one point on the timeline. Lane is the row (a worker, a server, a job).
// Kind is "begin" / "end" (a bar between them, matched by ID) or "mark" (a single point);
// Bad marks the event as a failure (a crash, a lost message) and draws it in red.
type Event struct {
	T       float64 `json:"t"`
	Lane    string  `json:"lane"`
	Kind    string  `json:"k"`
	ID      string  `json:"id,omitempty"`
	Label   string  `json:"label,omitempty"`
	LabelEn string  `json:"label_en,omitempty"` // shown in English mode; leave empty for language-neutral labels
	Bad     bool    `json:"bad,omitempty"`
}

// Trace collects events for one test. It is safe for concurrent use.
type Trace struct {
	mu     sync.Mutex
	start  time.Time
	events []Event
}

func NewTrace() *Trace { return &Trace{start: time.Now()} }

// Now is the number of seconds since the trace started.
func (tr *Trace) Now() float64 { return time.Since(tr.start).Seconds() }

// Add records an event whose label is the same in both languages (a task name, a method name).
func (tr *Trace) Add(lane, kind, id, label string, bad bool) { tr.AddL(lane, kind, id, label, "", bad) }

// AddL records an event with a Chinese and an English label, e.g. AddL(c, "mark", "", "请求丢了", "request lost", true).
func (tr *Trace) AddL(lane, kind, id, zh, en string, bad bool) {
	tr.mu.Lock()
	tr.events = append(tr.events, Event{tr.Now(), lane, kind, id, zh, en, bad})
	tr.mu.Unlock()
}

// Save writes the trace for the web UI, if DOJO_TRACE_DIR is set (the runner sets it).
func (tr *Trace) Save(test string) {
	dir := os.Getenv("DOJO_TRACE_DIR")
	if dir == "" {
		return
	}
	tr.mu.Lock()
	data, _ := json.Marshal(map[string]interface{}{"t_end": tr.Now(), "events": tr.events})
	tr.mu.Unlock()
	os.WriteFile(filepath.Join(dir, strings.ReplaceAll(test, "/", "_")+".json"), data, 0o644)
}
